// Entity — PostgreSQL-specific JSONB mapping via Hibernate 6 SqlTypes
import jakarta.persistence.*;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;
import java.time.OffsetDateTime;
import java.util.Map;

@Entity
@Table(name = "products")
public class Product {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false) private String name;

    // PostgreSQL: jsonb column. MySQL equivalent would be json + generated columns
    @JdbcTypeCode(SqlTypes.JSON)
    @Column(columnDefinition = "jsonb")
    private Map<String, Object> attributes;

    // PostgreSQL-native timestamptz; MySQL uses DATETIME + session TZ
    @Column(name = "created_at", nullable = false,
            columnDefinition = "timestamptz default now()")
    private OffsetDateTime createdAt;
}

// Repository — JSONB containment via native query
public interface ProductRepository extends JpaRepository<Product, Long> {
    @Query(value = "SELECT * FROM products WHERE attributes @> CAST(:filter AS jsonb)",
           nativeQuery = true)
    List<Product> findByAttributeContains(@Param("filter") String filterJson);
}

// Flyway migration — PostgreSQL lets you run DDL inside a transaction,
// so a failed step rolls back cleanly. MySQL auto-commits each DDL.
// V1__init.sql
// BEGIN;
// CREATE TABLE products (
//     id         BIGSERIAL PRIMARY KEY,
//     name       TEXT NOT NULL,
//     attributes JSONB NOT NULL DEFAULT '{}'::jsonb,
//     created_at TIMESTAMPTZ NOT NULL DEFAULT now()
// );
// CREATE INDEX idx_products_attrs_gin ON products USING GIN (attributes jsonb_path_ops);
// COMMIT;

**Schema validation with pg_jsonschema**
- Extension that enforces JSON Schema via CHECK constraints at the database
- Prevents application bugs from corrupting the JSONB shape across millions of rows

```sql
CREATE EXTENSION pg_jsonschema;
ALTER TABLE products ADD CONSTRAINT attrs_schema CHECK (
    jsonb_matches_schema('{
      "type":"object",
      "required":["sku"],
      "properties":{
        "sku":   {"type":"string","pattern":"^[A-Z]{3}-\\d{6}$"},
        "price": {"type":"number","minimum":0}
      }
    }'::jsonb, attributes)
);
```

**Partial updates**
- `jsonb_set(target, path, value, create_if_missing)` edits one path; rest of the row is untouched logically but rewritten physically per MVCC
- For bulk edits of nested paths prefer `||` merge: `attributes || '{"featured":true}'::jsonb`
- TOAST-compressed large JSONB rewrites are expensive — push hot fields to typed columns

