}

// Query via native SQL — JPQL has no @> operator
public interface ProductRepo extends JpaRepository<Product, Long> {
    @Query(value = "SELECT * FROM products " +
                   "WHERE attributes @> CAST(:filter AS jsonb)",
           nativeQuery = true)
    List<Product> findMatching(@Param("filter") String filter);
}
```

**Hibernate Hypersistence Utilities**
- For strongly typed JSONB records (`@Type(JsonType.class)` against a POJO)
- Valuable when attributes have a stable schema — otherwise `Map<String, Object>` is more flexible

-- Classic write skew: two on-call doctors. Policy says at least one must stay on call.
-- Table:
CREATE TABLE doctors (
    id       BIGINT PRIMARY KEY,
    on_call  BOOLEAN NOT NULL
);
INSERT INTO doctors VALUES (1, TRUE), (2, TRUE);

-- Two concurrent transactions under Repeatable Read
-- Both see two on-call doctors and each decides it is safe to go off-call

-- Session A                                     -- Session B
BEGIN ISOLATION LEVEL REPEATABLE READ;            BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM doctors WHERE on_call;       SELECT count(*) FROM doctors WHERE on_call;
-- returns 2                                      -- returns 2
UPDATE doctors SET on_call = FALSE WHERE id = 1;  UPDATE doctors SET on_call = FALSE WHERE id = 2;
COMMIT;                                            COMMIT;

-- Both commit. Result: zero doctors on call. Write skew achieved under RR.

-- Same scenario under Serializable — SSI aborts one
BEGIN ISOLATION LEVEL SERIALIZABLE;
-- ... same steps ...
COMMIT;
-- ERROR:  could not serialize access due to read/write dependencies among transactions
-- DETAIL: Reason code: Canceled on identification as a pivot, during commit attempt.
-- HINT: The transaction might succeed if retried.
-- SQLSTATE: 40001

-- FOR UPDATE — pessimistic alternative under Read Committed
-- Serializes access to the specific rows without using SERIALIZABLE
BEGIN;
SELECT * FROM accounts WHERE id IN (1, 2) ORDER BY id FOR UPDATE;
-- Row-level exclusive lock held until COMMIT; prevents concurrent modification
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- Inspect MVCC state
SELECT xmin, xmax, * FROM accounts WHERE id = 1;

-- Find long transactions that block VACUUM
SELECT pid, now() - xact_start AS duration, state, query
FROM pg_stat_activity
WHERE xact_start IS NOT NULL
ORDER BY duration DESC
LIMIT 10;

-- Guardrail — terminate idle-in-transaction sessions
ALTER SYSTEM SET idle_in_transaction_session_timeout = '60s';
SELECT pg_reload_conf();

// Default: READ_COMMITTED is correct for most OLTP
@Transactional
public void markOrderPaid(long orderId) {
    Order order = orderRepo.findById(orderId).orElseThrow();
    order.setStatus(PAID);
    // each statement sees latest committed data
}

// Consistent multi-statement read across a report — REPEATABLE_READ
@Transactional(isolation = Isolation.REPEATABLE_READ, readOnly = true)
public DailyReport buildReport(LocalDate day) {
    var rows = reportRepo.findByDay(day);      // snapshot
    var total = reportRepo.sumByDay(day);      // same snapshot
    return new DailyReport(rows, total);
}

// Business rule that must be serializable (write skew)
@Retryable(value = CannotSerializeTransactionException.class,
           maxAttempts = 3,
           backoff = @Backoff(delay = 50, multiplier = 2.0))
@Transactional(isolation = Isolation.SERIALIZABLE)
public void goOffCall(long doctorId) {
    long still = doctorRepo.countOnCall();
    if (still <= 1) throw new MustStayOnCallException();
    doctorRepo.setOffCall(doctorId);
}

// Pessimistic row lock — SELECT ... FOR UPDATE via Spring Data
public interface AccountRepo extends JpaRepository<Account, Long> {
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select a from Account a where a.id = :id")
    Account lockById(@Param("id") long id);
}

// Optimistic locking via JPA @Version — often cheaper than SERIALIZABLE
@Entity
public class Account {
    @Id private Long id;
    @Version private Long version;  // Hibernate adds WHERE version=? to UPDATE
    private BigDecimal balance;
}

-- 1. RANGE partitioning on a time column — the dominant pattern
CREATE TABLE events (
    id         BIGSERIAL,
    user_id    BIGINT NOT NULL,
    event_type TEXT   NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    payload    JSONB,
    PRIMARY KEY (created_at, id)        -- partition key MUST be in unique constraints
) PARTITION BY RANGE (created_at);

-- 2. Monthly partitions
CREATE TABLE events_2026_01 PARTITION OF events
    FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');
CREATE TABLE events_2026_02 PARTITION OF events
    FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');
CREATE TABLE events_2026_03 PARTITION OF events
    FOR VALUES FROM ('2026-03-01') TO ('2026-04-01');

-- Default partition catches out-of-range rows instead of erroring (PG 11+)
CREATE TABLE events_default PARTITION OF events DEFAULT;

-- 3. Index on the parent — cascades to all current and future partitions (PG 11+)
CREATE INDEX idx_events_user_created ON events (user_id, created_at DESC);

-- 4. Partition pruning in EXPLAIN
EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM events
WHERE created_at >= '2026-02-10' AND created_at < '2026-02-20'
  AND user_id = 42;
-- Append
--  -> Index Scan using events_2026_02_user_id_created_at_idx on events_2026_02
--     Index Cond: (user_id = 42 AND created_at >= ... AND created_at < ...)
-- (Only events_2026_02 is scanned — pruning worked)

-- 5. Without the partition key, every partition is scanned
EXPLAIN
SELECT count(*) FROM events WHERE user_id = 42;
-- Append scans events_2026_01, events_2026_02, events_2026_03, events_default
-- Slower than the equivalent query on a non-partitioned table

-- 6. Instant archive: detach + drop
ALTER TABLE events DETACH PARTITION events_2025_01 CONCURRENTLY;
-- events_2025_01 is now a standalone table; export or drop without affecting parent
DROP TABLE events_2025_01;

-- 7. LIST partitioning — tenant-scoped multi-tenant table
CREATE TABLE documents (
    id BIGSERIAL, tenant_id INT NOT NULL, body JSONB,
    PRIMARY KEY (tenant_id, id)
) PARTITION BY LIST (tenant_id);
CREATE TABLE documents_tenant_1 PARTITION OF documents FOR VALUES IN (1);
CREATE TABLE documents_tenant_2 PARTITION OF documents FOR VALUES IN (2);

-- 8. HASH partitioning — distributes rows evenly, no pruning for selective reads
CREATE TABLE jobs (
    id BIGSERIAL, user_id BIGINT NOT NULL, body JSONB,
    PRIMARY KEY (user_id, id)
) PARTITION BY HASH (user_id);
CREATE TABLE jobs_0 PARTITION OF jobs FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE jobs_1 PARTITION OF jobs FOR VALUES WITH (MODULUS 4, REMAINDER 1);
CREATE TABLE jobs_2 PARTITION OF jobs FOR VALUES WITH (MODULUS 4, REMAINDER 2);
CREATE TABLE jobs_3 PARTITION OF jobs FOR VALUES WITH (MODULUS 4, REMAINDER 3);

-- 9. pg_partman — automate creation, retention, and cleanup
CREATE EXTENSION pg_partman;
SELECT partman.create_parent(
    p_parent_table => 'public.events',
    p_control      => 'created_at',
    p_type         => 'native',
    p_interval     => 'monthly',
    p_premake      => 4
);
UPDATE partman.part_config
   SET retention = '12 months',
       retention_keep_table = false
 WHERE parent_table = 'public.events';
-- Scheduled maintenance (pg_cron or external scheduler)
-- SELECT partman.run_maintenance();

