import io.hypersistence.utils.hibernate.type.json.JsonType;
import jakarta.persistence.*;
import org.hibernate.annotations.*;
import org.hibernate.type.SqlTypes;

import java.math.BigDecimal;
import java.time.OffsetDateTime;
import java.util.List;
import java.util.Map;

@Entity
@Table(name = "orders")
public class OrderEntity {

    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "customer_id", nullable = false)
    private Long customerId;

    @Enumerated(EnumType.STRING)   // store as TEXT, not ORDINAL
    @Column(nullable = false, length = 32)
    private OrderStatus status;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal total;

    // ---- JSONB via Hibernate 6 built-in ----
    @JdbcTypeCode(SqlTypes.JSON)
    @Column(columnDefinition = "jsonb", nullable = false)
    private Map<String, Object> metadata;

    // ---- JSONB as a typed POJO via Hypersistence Utilities ----
    @Type(JsonType.class)
    @Column(columnDefinition = "jsonb")
    private ShippingInfo shipping;

    // ---- Native array type (text[]) ----
    @JdbcTypeCode(SqlTypes.ARRAY)
    @Column(columnDefinition = "text[]")
    private List<String> tags;

    // ---- Native array type (int[]) ----
    @JdbcTypeCode(SqlTypes.ARRAY)
    @Column(columnDefinition = "int[]")
    private int[] promotionIds;

    // ---- timestamptz (TIMESTAMP WITH TIME ZONE) ----
    @Column(name = "created_at", nullable = false,
            columnDefinition = "timestamptz default now()")
    private OffsetDateTime createdAt;

    @Version   // optimistic locking
    private Long version;

    // getters/setters omitted
}

public record ShippingInfo(String carrier, String tracking, Integer weightGrams) {}
public enum OrderStatus { PENDING, CONFIRMED, SHIPPED, CANCELLED }

import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import jakarta.persistence.LockModeType;
import java.util.List;

public interface OrderRepository extends JpaRepository<OrderEntity, Long> {

    // JSONB containment (@>): JPQL cannot express this
    @Query(value = "SELECT * FROM orders " +
                   "WHERE metadata @> CAST(:filter AS jsonb) " +
                   "ORDER BY created_at DESC LIMIT :limit",
           nativeQuery = true)
    List<OrderEntity> searchByMetadata(@Param("filter") String filterJson,
                                       @Param("limit") int limit);

    // Array overlap (&&) — any matching tag
    @Query(value = "SELECT * FROM orders WHERE tags && CAST(:tags AS text[])",
           nativeQuery = true)
    List<OrderEntity> findByAnyTag(@Param("tags") String[] tags);

    // FULL-TEXT SEARCH on a generated tsvector column
    @Query(value = "SELECT * FROM orders " +
                   "WHERE search_vector @@ websearch_to_tsquery('english', :q) " +
                   "ORDER BY ts_rank_cd(search_vector, websearch_to_tsquery('english', :q)) DESC " +
                   "LIMIT :limit",
           nativeQuery = true)
    List<OrderEntity> fullTextSearch(@Param("q") String query,
                                     @Param("limit") int limit);

    // Pessimistic row lock (SELECT ... FOR UPDATE)
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select o from OrderEntity o where o.id = :id")
    OrderEntity lockForProcessing(@Param("id") Long id);

    // Queue pattern — SKIP LOCKED, index on status + id
    @Query(value = "SELECT * FROM orders " +
                   "WHERE status = 'PENDING' " +
                   "ORDER BY id " +
                   "FOR UPDATE SKIP LOCKED " +
                   "LIMIT :n",
           nativeQuery = true)
    List<OrderEntity> pickBatch(@Param("n") int batchSize);
}

// Transaction-scoped advisory lock — PgBouncer-transaction-pooling safe
// (pg_advisory_lock is SESSION-scoped and breaks under transaction pooling)
public interface AdvisoryLockRepository extends Repository<OrderEntity, Long> {
    @Query(value = "SELECT pg_try_advisory_xact_lock(hashtext(:key))",
           nativeQuery = true)
    Boolean tryLock(@Param("key") String key);
}

import org.springframework.dao.CannotSerializeTransactionException;
import org.springframework.retry.annotation.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

@Service
@Transactional
public class OrderService {

    private final OrderRepository repo;
    private final AdvisoryLockRepository locks;
    private final ApplicationEventPublisher events;

    public OrderService(OrderRepository repo, AdvisoryLockRepository locks,
                        ApplicationEventPublisher events) {
        this.repo = repo; this.locks = locks; this.events = events;
    }

    // READ_COMMITTED (default) is correct for most OLTP
    public OrderEntity confirm(long id) {
        OrderEntity o = repo.lockForProcessing(id);
        o.setStatus(OrderStatus.CONFIRMED);
        return o;
    }

    // REPEATABLE_READ for consistent multi-query reports
    @Transactional(isolation = Isolation.REPEATABLE_READ, readOnly = true)
    public Report buildReport(LocalDate day) { /* ... */ }

    // Business invariant that requires SERIALIZABLE + retry
    @Retryable(value = CannotSerializeTransactionException.class,
               maxAttempts = 3, backoff = @Backoff(delay = 50, multiplier = 2.0))
    @Transactional(isolation = Isolation.SERIALIZABLE)
    public void assignExclusive(long orderId, long workerId) { /* ... */ }

    // ------------------------------------------------------------
    // LISTEN / NOTIFY caveat under PgBouncer transaction pooling:
    // LISTEN binds to the server connection. In transaction pooling,
    // the next transaction may land on a different backend — your LISTEN is lost.
    //
    // Three production patterns:
    //   1. Switch to PgBouncer session pooling for the listening connection
    //   2. Use an 'outbox' table + polling + SKIP LOCKED (see pickBatch)
    //   3. Use Debezium + Kafka for CDC
    //
    // If you still want LISTEN/NOTIFY, open a dedicated DataSource that
    // talks directly to PostgreSQL (not through PgBouncer) and keep the
    // connection open for the life of the application.
    // ------------------------------------------------------------

    // Transaction-scoped advisory lock for cross-instance coordination
    public void runSingletonJob(String jobKey, Runnable work) {
        if (Boolean.TRUE.equals(locks.tryLock(jobKey))) {
            work.run();
        } // else: another instance already holds the lock for this transaction
    }
}

**Testing against real PostgreSQL**
- Use Testcontainers with the matching minor version: `PostgreSQLContainer("postgres:16.4-alpine")`
- Spin a fresh container per test class for schema isolation; reuse across tests within a class
- Never test JSONB or array mapping against H2 — behaviour differs materially

```java
@Testcontainers @SpringBootTest
class OrderRepoIT {
    @Container
    static PostgreSQLContainer<?> pg =
        new PostgreSQLContainer<>("postgres:16.4-alpine")
            .withCommand("postgres", "-c", "fsync=off");

    @DynamicPropertySource
    static void props(DynamicPropertyRegistry r) {
        r.add("spring.datasource.url", pg::getJdbcUrl);
        r.add("spring.datasource.username", pg::getUsername);
        r.add("spring.datasource.password", pg::getPassword);
    }
}
```

**Migration discipline**
- Flyway handles transactional DDL automatically — a failing migration rolls back cleanly on PostgreSQL
- `CREATE INDEX CONCURRENTLY` cannot run inside a transaction — put it in its own migration file and mark it accordingly
- For online column changes: add column nullable → backfill → set NOT NULL in a later migration, never a single statement

**Operational runbook**
- Alert on HikariCP `pending > 0` for sustained periods and on PgBouncer `cl_waiting > 0`
- Alert on `pg_stat_activity` sessions older than 5 minutes (long transactions hurt VACUUM)
- Alert on `pg_replication_slots.wal_bytes_kept` above a threshold (orphaned slot risk)
- Enable `pg_stat_statements` and review top queries by `total_exec_time` weekly
- Maintain an index hygiene script: unused indexes with `idx_scan = 0` after 30 days, bloated indexes via `pgstattuple`

**Graceful shutdown**
- `server.shutdown: graceful` lets in-flight requests finish before the pod exits
- HikariCP drains idle connections cleanly; long transactions should hit `statement_timeout` before SIGKILL arrives
